def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    stack: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if token and all(c in "0123456789" for c in token):
            return int(token)
        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False

        if verb == "open" and len(parts) == 3:
            account, amount = parts[1], parse_amount(parts[2])
            if amount is not None and account not in balances:
                balances[account] = amount
                stack.append(("open", account))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            account, amount = parts[1], parse_amount(parts[2])
            if amount is not None and amount > 0 and account in balances:
                balances[account] += amount
                stack.append(("deposit", account, amount))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            account, amount = parts[1], parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and account in balances
                and account not in frozen
                and balances[account] >= amount
            ):
                balances[account] -= amount
                stack.append(("withdraw", account, amount))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            source, dest, amount = parts[1], parts[2], parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and source != dest
                and source in balances
                and dest in balances
                and source not in frozen
                and balances[source] >= amount
            ):
                balances[source] -= amount
                balances[dest] += amount
                stack.append(("transfer", source, dest, amount))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            account = parts[1]
            if account in balances and account not in frozen:
                frozen.add(account)
                stack.append(("freeze", account))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            account = parts[1]
            if account in balances and account in frozen:
                frozen.remove(account)
                stack.append(("unfreeze", account))
                ok = True
        elif verb == "undo" and len(parts) == 1 and stack:
            kind = stack.pop()
            action = kind[0]
            if action == "open":
                del balances[kind[1]]
                frozen.discard(kind[1])
            elif action == "deposit":
                balances[kind[1]] -= kind[2]
            elif action == "withdraw":
                balances[kind[1]] += kind[2]
            elif action == "transfer":
                balances[kind[1]] += kind[3]
                balances[kind[2]] -= kind[3]
            elif action == "freeze":
                frozen.discard(kind[1])
            elif action == "unfreeze":
                frozen.add(kind[1])
            ok = True

        if not ok:
            rejected.append(i)

    return balances, rejected
